"""Test case for the list of futures fix that could be added to the official test suite"""

from tornado import gen
from tornado.concurrent import return_future
from tornado.testing import AsyncTestCase


class FutureListFixTest(AsyncTestCase):
    @return_future
    def async_future(self, result, callback): 
        self.io_loop.add_callback(callback, result)

    def test_list_of_futures(self):
        """Test that yielding a list of Future objects works correctly"""
        @gen.engine
        def f():
            results = yield [self.async_future(1), self.async_future(2)]
            self.assertEqual(results, [1, 2])
            self.stop()

        f()
        self.wait()

    def test_mixed_list_of_futures_and_yieldpoints(self):
        """Test that yielding a mixed list of Future objects and YieldPoint objects works correctly"""
        @gen.engine
        def f():
            def simple_task(callback):
                callback("task_result")

            results = yield [
                self.async_future("future_result"), 
                gen.Task(simple_task)
            ]
            self.assertEqual(results, ["future_result", "task_result"])
            self.stop()

        f()
        self.wait()

    def test_empty_list_of_futures(self):
        """Test that yielding an empty list works correctly"""
        @gen.engine
        def f():
            results = yield []
            self.assertEqual(results, [])
            self.stop()

        f()
        self.wait()

    def test_single_future_in_list(self):
        """Test that yielding a list with a single Future works correctly"""
        @gen.engine
        def f():
            results = yield [self.async_future("single")]
            self.assertEqual(results, ["single"])
            self.stop()

        f()
        self.wait()


