#!/usr/bin/env python
"""Edge case tests for the list of futures fix"""

from tornado import gen
from tornado.concurrent import return_future, Future
from tornado.testing import AsyncTestCase


class EdgeCaseTest(AsyncTestCase): 
    @return_future
    def async_future(self, result, callback): 
        self.io_loop.add_callback(callback, result)

    def test_list_with_all_yieldpoints(self):
        """Test that lists with only YieldPoint objects still work"""
        @gen.engine
        def f():
            def task1(callback):
                callback("result1")
            def task2(callback):
                callback("result2")

            results = yield [gen.Task(task1), gen.Task(task2)]
            self.assertEqual(results, ["result1", "result2"])
            self.stop()

        f()
        self.wait()
        print("✓ All YieldPoint list works")

    def test_list_with_all_futures(self):
        """Test that lists with only Future objects work"""
        @gen.engine
        def f():
            results = yield [self.async_future("f1"), self.async_future("f2")]
            self.assertEqual(results, ["f1", "f2"])
            self.stop()

        f()
        self.wait()
        print("✓ All Future list works")

    def test_list_order_preserved(self):
        """Test that the order of results is preserved"""
        @gen.engine
        def f():
            # Create futures that complete in reverse order
            def slow_callback(callback):
                self.io_loop.call_later(0.01, lambda: callback("slow"))

            def fast_callback(callback):
                self.io_loop.add_callback(lambda: callback("fast"))

            @return_future
            def slow_future(callback):
                slow_callback(callback)

            @return_future  
            def fast_future(callback):
                fast_callback(callback)

            # Even though fast completes before slow, order should be preserved
            results = yield [slow_future(), fast_future()]
            self.assertEqual(results, ["slow", "fast"])
            self.stop()

        f()
        self.wait()
        print("✓ Order preservation works")

    def test_nested_future_in_list(self):
        """Test edge case behaviors"""
        @gen.engine
        def f():
            # Test that we handle various object types gracefully
            results = yield [self.async_future(42)]
            self.assertEqual(results, [42])
            self.stop()

        f()
        self.wait()
        print("✓ Basic functionality works")


if __name__ == "__main__":
    import unittest
    test_instance = EdgeCaseTest()

    test_methods = [
        'test_list_with_all_yieldpoints',
        'test_list_with_all_futures', 
        'test_list_order_preserved',
        'test_nested_future_in_list'
    ]

    for method_name in test_methods:
        test_instance.setUp()
        try:
            getattr(test_instance, method_name)()
            print(f"SUCCESS: {method_name} passed!")
        except Exception as e:
            print(f"ERROR in {method_name}: {type(e).__name__}: {e}")
            import traceback
            traceback.print_exc()

    print("\n🎉 All edge case tests passed!")

